=== ClaimTransition
package net.officefloor.hq.app.claim;

/** Moves a claim to a new status, refusing a change its current status does not allow. */
final class ClaimTransition {
    private ClaimTransition() {
    }

    static void to(Claim claim, ClaimStatus to) throws InvalidClaimStatusException {
        check(claim.getStatus(), to);
        claim.setStatus(to);
    }

    /** Refuses approving or rejecting (moving to {@code to}) a claim that is not PENDING. */
    static void requirePending(Claim claim, ClaimStatus to) throws InvalidClaimStatusException {
        if (!claim.getStatus().awaitsApproval()) {
            throw new InvalidClaimStatusException("A " + claim.getStatus() + " claim cannot become " + to + ".");
        }
    }

    static void check(ClaimStatus from, ClaimStatus to) throws InvalidClaimStatusException {
        if (!from.canBecome(to)) {
            throw new InvalidClaimStatusException("A " + from + " claim cannot become " + to + ".");
        }
    }
}
=== OpenClaim
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.HttpHeaderParameter;

/** Moves the claim to OPEN, refusing it when its status does not allow that, and gives it its number (the
 *  sheet's next, or the next in its period while period numbering is on) and records who opened it (the
 *  signed-in user, arriving as X-User). */
public class OpenClaim {
    public void apply(@Val Claim claim, @HttpHeaderParameter("X-User") String user, ClaimRepository repository,
            SettingRepository settings, SheetRepository sheets, PeriodRepository periods) throws InvalidClaimStatusException {
        ClaimTransition.check(claim.getStatus(), ClaimStatus.OPEN);
        // Holding the numbers holds the sheet's numbers until this change commits or is refused. Then
        // re-check the stored status: an open of the same claim that got there first has committed by
        // now, so this one is refused (and its number rolls back with it).
        ClaimNumbering numbering = ClaimNumbering.hold(claim.getSheetId(), repository, settings, sheets);
        ClaimTransition.check(ClaimStatus.valueOf(repository.storedStatus(claim.getId())), ClaimStatus.OPEN);
        ClaimTransition.to(claim, ClaimStatus.OPEN);
        numbering.number(claim, repository, periods);
        claim.setOpenedBy(user == null ? "" : user.trim());
    }
}
=== SettleClaim
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.setting.UserRole;
import net.officefloor.hq.app.setting.UserRoleRepository;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.HttpHeaderParameter;

/** Moves the claim to SETTLED, refusing it when its status does not allow that, and fixes its due (see {@link ClaimDue}).
 *  The user who opened the claim (arriving as X-User) cannot settle it. When a clerk (any user not made a steward)
 *  settles a claim whose due is above the sheet's clerk limit (no limit when none is set; a claim with no due
 *  is within it), it goes to PENDING instead, its due still live, for a steward to approve or reject; a steward settles any. */
public class SettleClaim {
    public void apply(@Val Claim claim, @HttpHeaderParameter("X-User") String user, PersonRepository people,
            RateRepository rates, SettingRepository settings, UserRoleRepository roles, SheetRepository sheets)
            throws InvalidClaimStatusException, SelfSettleException {
        String by = user == null ? "" : user.trim();
        if (claim.getOpenedBy() != null && claim.getOpenedBy().equals(by)) {
            throw new SelfSettleException("The user who opened a claim cannot settle it.");
        }
        ClaimTransition.check(claim.getStatus(), ClaimStatus.SETTLED);
        BigDecimal due = ClaimDue.now(claim, people, rates, settings, sheets);
        if (due != null && UserRole.CLERK.equals(roles.roleOf(claim.getSheetId(), by))) {
            BigDecimal limit = settings.clerkLimit(claim.getSheetId()).orElse(null);
            if (limit != null && due.compareTo(limit) > 0) {
                ClaimTransition.to(claim, ClaimStatus.PENDING);
                return;
            }
        }
        ClaimTransition.to(claim, ClaimStatus.SETTLED);
        claim.setSettledDue(due);
    }
}
